Looking at the kernel, I need to analyze the access patterns:

1. The outer loops iterate over `i` (0..M) and `j` (0..N)
2. The inner `k` loop has a loop-carried dependency through `C[k][j]` (written in different `i` iterations) and accumulates `temp2`
3. Arrays `C`, `A`, `B` are 2D arrays passed as pointers - need m_axi interfaces
4. The inner `k` loop dependency on `C[k][j]` prevents simple pipelining of the innermost loop without care

Key optimizations:
- Add proper HLS INTERFACE pragmas for all ports
- Pipeline the innermost `k` loop (noting `C[k][j]` write creates a WAW/RAW hazard across `i` iterations, but within a single `i` iteration the `k` loop body has no loop-carried dependency on `temp2` from `C[k][j]` writes)
- Add ARRAY_PARTITION on the innermost dimension for better memory access
- Pipeline the `j` loop where possible

```cpp
#include "symm.h"

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M + 0][N + 0],
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local tiles for staging working sets
    double A_row[M];      // A[i][0..i]
    double B_row_i[N];    // B[i][0..n]
    double C_col[M];      // C[0..i][j] staging

#pragma HLS ARRAY_PARTITION variable=A_row  cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row_i cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=C_col  cyclic factor=4 dim=1

    int i, j, k;
    double temp2;

    for (i = 0; i < m; i++) {
        // Load A[i][0..i] into local buffer
        load_A: for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
            A_row[k] = A[i][k];
        }
        // Also load A[i][i]
        double A_ii = A[i][i];

        // Load B[i][0..n] into local buffer
        load_B: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B_row_i[j] = B[i][j];
        }

        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            // Load C[0..i][j] into local staging buffer
            // We need to update C[k][j] for k < i and C[i][j]
            // This inner loop over k cannot be pipelined here inside j-pipeline
            // so we handle with the outer j loop pipeline
            double Bval = B_row_i[j];
            double alpha_Bval = alpha * Bval;
            double Cij = C[i][j];
            temp2 = 0.0;

            // k-loop: update C[k][j] and accumulate temp2
            // This creates a dependency: can pipeline with II=1 if no RAW on C[k][j]
            // across different j (same k, different j is fine as they're different elements)
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=C inter false
                double Aik = A_row[k];
                double Bkj = B[k][j];
                C[k][j] += alpha_Bval * Aik;
                temp2 += Bkj * Aik;
            }
            C[i][j] = beta * Cij + alpha_Bval * A_ii + alpha * temp2;
        }
    }
}

} // extern "C"
```

Looking at the current code, I need to apply tiling optimization to improve memory locality. The key insight is that `B[k][j]` and `C[k][j]` are accessed repeatedly across the outer `i` loop for the same column `j`, and we can tile across the `j` (column) dimension to buffer chunks of B and C into local arrays, reducing global memory traffic.

The tiling strategy:
- Tile the `j` dimension (columns) into chunks of size `TILE_N`
- For each tile of columns, load the relevant portion of B and C into local buffers
- Perform compute on local buffers
- Store results back

```cpp
#include "symm.h"

#define TILE_N 16
#define TILE_M 16

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M + 0][N + 0],
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local tile buffers
    double A_tile[TILE_M][TILE_M];   // tile of A rows
    double B_tile[TILE_M][TILE_N];   // tile of B[k][j_tile]
    double C_tile[TILE_M][TILE_N];   // tile of C[i_tile][j_tile]
    double A_row[M];                  // A[i][0..i] for current row i

#pragma HLS ARRAY_PARTITION variable=A_tile  cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=B_tile  cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=C_tile  cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=A_row   cyclic factor=4 dim=1

    int i, j, k;

    // Tile over columns (j dimension)
    for (int jt = 0; jt < n; jt += TILE_N) {
        int j_end = (jt + TILE_N < n) ? (jt + TILE_N) : n;
        int j_len = j_end - jt;

        // Tile over rows (i dimension)
        for (int it = 0; it < m; it += TILE_M) {
            int i_end = (it + TILE_M < m) ? (it + TILE_M) : m;
            int i_len = i_end - it;

            // -------------------------------------------------------
            // LOAD PHASE: Load C tile [it..i_end][jt..j_end]
            // -------------------------------------------------------
            load_C: for (int li = 0; li < i_len; li++) {
                for (int lj = 0; lj < j_len; lj++) {
#pragma HLS PIPELINE II=1
                    C_tile[li][lj] = C[it + li][jt + lj];
                }
            }

            // Load A sub-block for rows [it..i_end], cols [0..i_end]
            // We need A[i][k] for k < i, so load A rows for current i tile
            load_A_tile: for (int li = 0; li < i_len; li++) {
                int row = it + li;
                for (int lk = 0; lk <= row && lk < m; lk++) {
#pragma HLS PIPELINE II=1
                    A_row[lk] = A[row][lk];
                }
                // Store into A_tile for later use (only the diagonal element matters per-row)
                // We store A[row][row] at A_tile[li][li]
                A_tile[li][0] = A[row][row]; // diagonal
            }

            // -------------------------------------------------------
            // COMPUTE PHASE: For each i in [it, i_end), each j in [jt, j_end)
            // Perform the symmetric matrix update using local buffers
            // -------------------------------------------------------
            compute_i: for (i = it; i < i_end; i++) {
                int li = i - it;
                double A_ii = A[i][i];

                // Load A[i][0..i] into A_row
                load_Arow: for (k = 0; k <= i; k++) {
#pragma HLS PIPELINE II=1
                    A_row[k] = A[i][k];
                }

                // Load B[i][jt..j_end] into a local row buffer
                double B_row_i[TILE_N];
#pragma HLS ARRAY_PARTITION variable=B_row_i cyclic factor=4 dim=1
                load_Bi: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    B_row_i[j] = B[i][jt + j];
                }

                // Load B[k][jt..j_end] for k < i into B_tile
                load_Bk: for (k = 0; k < i; k++) {
                    for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                        B_tile[k % TILE_M][j] = B[k][jt + j];
                    }
                }

                // Load C[k][jt..j_end] for k < i into a staging buffer, compute, store back
                // For k < i: C[k][j] += alpha * B[i][j] * A[i][k]
                update_Ck: for (k = 0; k < i; k++) {
                    double Aik = A_row[k];
                    double C_kj_tile[TILE_N];
#pragma HLS ARRAY_PARTITION variable=C_kj_tile cyclic factor=4 dim=1

                    // Load C[k][jt..j_end]
                    load_Ckj: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                        C_kj_tile[j] = C[k][jt + j];
                    }

                    // Update C[k][j] and store back
                    update_Ckj: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                        C_kj_tile[j] += alpha * B_row_i[j] * Aik;
                    }

                    // Store C[k][jt..j_end]
                    store_Ckj: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                        C[k][jt + j] = C_kj_tile[j];
                    }
                }

                // Update C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i] + alpha*sum_k(B[k][j]*A[i][k])
                update_Ci: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    double Cij = C_tile[li][j];
                    double Bval = B_row_i[j];
                    double temp2 = 0.0;

                    // Accumulate temp2 from local B_tile
                    for (k = 0; k < i; k++) {
                        temp2 += B_tile[k % TILE_M][j] * A_row[k];
                    }
                    C_tile[li][j] = beta * Cij + alpha * Bval * A_ii + alpha * temp2;
                }
            }

            // -------------------------------------------------------
            // STORE PHASE: Write C tile back to global memory
            // -------------------------------------------------------
            store_C: for (int li = 0; li < i_len; li++) {
                for (int lj = 0; lj < j_len; lj++) {
#pragma HLS PIPELINE II=1
                    C[it + li][jt + lj] = C_tile[li][lj];
                }
            }
        }
    }
}

} // extern "C"
```

Wait, this approach has correctness issues because the `C[k][j]` updates in `update_Ck` conflict with the `C_tile` approach for the current tile. Let me restructure with a cleaner tile-based separation:

```cpp
#include "symm.h"

#define TILE_N 16

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M + 0][N + 0],
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local buffers for tiling over j dimension
    double A_row[M];           // A[i][0..i]
    double B_row_i[TILE_N];    // B[i][jt..jt+TILE_N]
    double B_kj[TILE_N];       // B[k][jt..jt+TILE_N]
    double C_kj[TILE_N];       // C[k][jt..jt+TILE_N]
    double C_ij[TILE_N];       // C[i][jt..jt+TILE_N]

#pragma HLS ARRAY_PARTITION variable=A_row   cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row_i cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_kj    cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=C_kj    cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=C_ij    cyclic factor=4 dim=1

    int i, j, k, jt;

    // Outer tile loop over columns
    for (jt = 0; jt < n; jt += TILE_N) {
        int j_len = ((jt + TILE_N) < n) ? TILE_N : (n - jt);

        // Process each row i
        for (i = 0; i < m; i++) {

            // ------------------------------------------
            // LOAD PHASE
            // ------------------------------------------

            // Load A[i][0..i] (symmetric part needed)
            load_A: for (k = 0; k <= i; k++) {
#pragma HLS PIPELINE II=1
                A_row[k] = A[i][k];
            }
            double A_ii = A_row[i];

            // Load B[i][jt..jt+j_len]
            load_Bi: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                B_row_i[j] = B[i][jt + j];
            }

            // Load C[i][jt..jt+j_len]
            load_Ci: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                C_ij[j] = C[i][jt + j];
            }

            // ------------------------------------------
            // COMPUTE + STORE for C[k][j], k < i
            // ------------------------------------------
            for (k = 0; k < i; k++) {
                double Aik = A_row[k];

                // Load B[k][jt..jt+j_len]
                load_Bk: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    B_kj[j] = B[k][jt + j];
                }

                // Load C[k][jt..jt+j_len]
                load_Ck: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C_kj[j] = C[k][jt + j];
                }

                // Compute update to C[k][j] and accumulate into C_ij (temp2)
                // C[k][j] += alpha * B[i][j] * A[i][k]
                compute_k: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C_kj[j] += alpha * B_row_i[j] * Aik;
                    // Also accumulate temp2 for C[i][j]: temp2 += B[k][j] * A[i][k]
                    C_ij[j] += alpha * B_kj[j] * Aik;
                }

                // Store C[k][jt..jt+j_len]
                store_Ck: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C[k][jt + j] = C_kj[j];
                }
            }

            // ------------------------------------------
            // COMPUTE C[i][j] final value
            // C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i] + alpha*temp2
            // Note: C_ij already holds beta*C[i][j] is not yet applied
            // We loaded C[i][j] and accumulated alpha*B[k][j]*A[i][k] into it
            // Need: beta*C_orig[i][j] + alpha*B[i][j]*A[i][i] + accumulated
            // But we added to C_orig not beta*C_orig, fix below:
            // ------------------------------------------
            // Actually C_ij was loaded as original C[i][j], then we added alpha*B[k][j]*A[i][k]
            // Final = beta * C_orig[i][j] + alpha * B[i][j] * A[i][i] + alpha * sum_k(B[k][j]*A[i][k])
            // So we need to track C_orig separately. Let's use a temp accumulator.

            // ------------------------------------------
            // STORE PHASE for C[i][j]
            // ------------------------------------------
            store_Ci: for (j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                // C_ij[j] currently = C_orig[i][j] + alpha*sum_k(B[k][j]*A[i][k])
                // We want: beta*C_orig[i][j] + alpha*B[i][j]*A[i][i] + alpha*sum_k(...)
                // = beta*(C_ij[j] - alpha*sum_k) + alpha*B[i][j]*A[i][i] + alpha*sum_k
                // This is getting complicated. Use a clean accumulator instead.
                C[i][jt + j] = C_ij[j] + alpha * B_row_i[j] * A_ii;
            }
        }
    }
}

} // extern "C"
```

The accumulation into `C_ij` above is still incorrect because `beta` scaling is wrong. Let me write this cleanly and correctly:

```cpp
#include "symm.h"

#define TILE_N 16

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M + 0][N + 0],
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local tile buffers - tile over columns (j-dimension) in chunks of TILE_N
    double A_row[M];           // A[i][0..i]  - full row of symmetric A
    double B_row_i[TILE_N];    // B[i][jt..jt+TILE_N]  - tile of row i of B
    double B_kj[TILE_N];       // B[k][jt..jt+TILE_N]  - tile of row k of B
    double C_kj[TILE_N];       // C[k][jt..jt+TILE_N]  - tile of row k of C (for update)
    double C_ij_orig[TILE_N];  // original C[i][jt..jt+TILE_N] before update
    double temp2_tile[TILE_N]; // accumulator for sum_k B[k][j]*A[i][k]

#pragma HLS ARRAY_PARTITION variable=A_row      cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row_i    cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_kj       cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=C_kj       cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=C_ij_orig  cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=temp2_tile cyclic factor=4 dim=1

    // Tile loop over j (columns)
    for (int jt = 0; jt < n; jt += TILE_N) {
        int j_len = ((jt + TILE_N) <= n) ? TILE_N : (n - jt);

        // Process each row i sequentially
        for (int i = 0; i < m; i++) {

            // ==================================================
            // LOAD PHASE
            // ==================================================

            // Load A[i][0..i] into local buffer
            load_A_row: for (int k = 0; k <= i; k++) {
#pragma HLS PIPELINE II=1
                A_row[k] = A[i][k];
            }
            double A_ii = A_row[i];

            // Load B[i][jt..jt+j_len] into local tile
            load_B_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                B_row_i[j] = B[i][jt + j];
            }

            // Load C[i][jt..jt+j_len] into local tile (original values)
            load_C_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                C_ij_orig[j] = C[i][jt + j];
            }

            // Initialize temp2 accumulator tile to zero
            init_temp2: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                temp2_tile[j] = 0.0;
            }

            // ==================================================
            // COMPUTE PHASE: loop over k < i
            // For each k: update C[k][j] and accumulate temp2
            // ==================================================
            compute_k: for (int k = 0; k < i; k++) {
                double Aik = A_row[k];

                // Load B[k][jt..jt+j_len]
                load_Bk: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    B_kj[j] = B[k][jt + j];
                }

                // Load C[k][jt..jt+j_len]
                load_Ck: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C_kj[j] = C[k][jt + j];
                }

                // Compute: C[k][j] += alpha * B[i][j] * A[i][k]
                //          temp2[j] += B[k][j] * A[i][k]
                compute_kj: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C_kj[j]      += alpha * B_row_i[j] * Aik;
                    temp2_tile[j] += B_kj[j] * Aik;
                }

                // Store C[k][jt..jt+j_len] back to global memory
                store_Ck: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                    C[k][jt + j] = C_kj[j];
                }
            }

            // ==================================================
            // COMPUTE + STORE PHASE: finalize C[i][j]
            // C[i][j] = beta*C_orig[i][j] + alpha*B[i][j]*A[i][i] + alpha*temp2[j]
            // ==================================================
            store_C_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
                C[i][jt + j] = beta * C_ij_orig[j]
                              + alpha * B_row_i[j] * A_ii
                              + alpha * temp2_tile[j];
            }
        }
    }
}

} // extern "C"
```

Looking at the current code, I can see that `PIPELINE II=1` pragmas are already applied to the inner loops. However, I need to add:

1. `#pragma HLS LOOP_TRIPCOUNT` for variable-bound loops (loops with variable bounds like `j_len` and `k <= i`)
2. `#pragma HLS DEPENDENCE` for false inter-iteration dependencies on local arrays accessed in pipelined loops
3. Additional `#pragma HLS ARRAY_PARTITION` where needed for parallel access

The key issues are:
- Variable-bound loops (`load_A_row` with `k <= i`, all loops with `j_len`) need `LOOP_TRIPCOUNT` for better scheduling estimates
- `temp2_tile` and `C_kj` arrays have potential false dependencies reported by HLS in the `compute_kj` loop
- The `compute_kj` loop accumulates into `temp2_tile` — HLS may see a false inter-iteration dependency

```cpp
#include "symm.h"

#define TILE_N 16

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M + 0][N + 0],
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local tile buffers - tile over columns (j-dimension) in chunks of TILE_N
    double A_row[M];           // A[i][0..i]  - full row of symmetric A
    double B_row_i[TILE_N];    // B[i][jt..jt+TILE_N]  - tile of row i of B
    double B_kj[TILE_N];       // B[k][jt..jt+TILE_N]  - tile of row k of B
    double C_kj[TILE_N];       // C[k][jt..jt+TILE_N]  - tile of row k of C (for update)
    double C_ij_orig[TILE_N];  // original C[i][jt..jt+TILE_N] before update
    double temp2_tile[TILE_N]; // accumulator for sum_k B[k][j]*A[i][k]

#pragma HLS ARRAY_PARTITION variable=A_row      cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row_i    complete dim=1
#pragma HLS ARRAY_PARTITION variable=B_kj       complete dim=1
#pragma HLS ARRAY_PARTITION variable=C_kj       complete dim=1
#pragma HLS ARRAY_PARTITION variable=C_ij_orig  complete dim=1
#pragma HLS ARRAY_PARTITION variable=temp2_tile complete dim=1

    // Tile loop over j (columns)
    for (int jt = 0; jt < n; jt += TILE_N) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        int j_len = ((jt + TILE_N) <= n) ? TILE_N : (n - jt);

        // Process each row i sequentially
        for (int i = 0; i < m; i++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60

            // ==================================================
            // LOAD PHASE
            // ==================================================

            // Load A[i][0..i] into local buffer
            load_A_row: for (int k = 0; k <= i; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=60
#pragma HLS DEPENDENCE variable=A_row inter false
                A_row[k] = A[i][k];
            }
            double A_ii = A_row[i];

            // Load B[i][jt..jt+j_len] into local tile
            load_B_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=B_row_i inter false
                B_row_i[j] = B[i][jt + j];
            }

            // Load C[i][jt..jt+j_len] into local tile (original values)
            load_C_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=C_ij_orig inter false
                C_ij_orig[j] = C[i][jt + j];
            }

            // Initialize temp2 accumulator tile to zero
            init_temp2: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=temp2_tile inter false
                temp2_tile[j] = 0.0;
            }

            // ==================================================
            // COMPUTE PHASE: loop over k < i
            // For each k: update C[k][j] and accumulate temp2
            // ==================================================
            compute_k: for (int k = 0; k < i; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=59
                double Aik = A_row[k];

                // Load B[k][jt..jt+j_len]
                load_Bk: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=B_kj inter false
                    B_kj[j] = B[k][jt + j];
                }

                // Load C[k][jt..jt+j_len]
                load_Ck: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=C_kj inter false
                    C_kj[j] = C[k][jt + j];
                }

                // Compute: C[k][j] += alpha * B[i][j] * A[i][k]
                //          temp2[j] += B[k][j] * A[i][k]
                compute_kj: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=C_kj       inter false
#pragma HLS DEPENDENCE variable=temp2_tile inter false
#pragma HLS DEPENDENCE variable=B_row_i    inter false
#pragma HLS DEPENDENCE variable=B_kj       inter false
                    C_kj[j]      += alpha * B_row_i[j] * Aik;
                    temp2_tile[j] += B_kj[j] * Aik;
                }

                // Store C[k][jt..jt+j_len] back to global memory
                store_Ck: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=C_kj inter false
                    C[k][jt + j] = C_kj[j];
                }
            }

            // ==================================================
            // COMPUTE + STORE PHASE: finalize C[i][j]
            // C[i][j] = beta*C_orig[i][j] + alpha*B[i][j]*A[i][i] + alpha*temp2[j]
            // ==================================================
            store_C_row_i: for (int j = 0; j < j_len; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=C_ij_orig  inter false
#pragma HLS DEPENDENCE variable=B_row_i    inter false
#pragma HLS DEPENDENCE variable=temp2_tile inter false
                C[i][jt + j] = beta * C_ij_orig[j]
                              + alpha * B_row_i[j] * A_ii
                              + alpha * temp2_tile[j];
            }
        }
    }
}

} // extern "C"
