```cpp
#include "symm.h"
#include <ap_int.h>
#include <string.h>

#define TILE_N 16
#define WIDE_BUS_WIDTH 512
#define DOUBLES_PER_WORD (WIDE_BUS_WIDTH / 64)  // 8 doubles per 512-bit word

typedef ap_uint<512> MARS_WIDE_BUS_TYPE;

// Helper: read j_len doubles from wide-bus memory into local array
// src_byte_offset must be aligned to sizeof(double)
static void read_doubles(double* dst, int dst_offset,
                         MARS_WIDE_BUS_TYPE* src, int src_byte_offset,
                         int num_doubles)
{
#pragma HLS INLINE
    int start_elem = src_byte_offset / sizeof(double);
    for (int j = 0; j < num_doubles; j++) {
#pragma HLS PIPELINE II=1
        int elem_idx = start_elem + j;
        int word_idx = elem_idx / DOUBLES_PER_WORD;
        int bit_offset = (elem_idx % DOUBLES_PER_WORD) * 64;
        ap_uint<64> bits = src[word_idx].range(bit_offset + 63, bit_offset);
        double val;
        memcpy(&val, &bits, sizeof(double));
        dst[dst_offset + j] = val;
    }
}

// Helper: write j_len doubles from local array into wide-bus memory
static void write_doubles(MARS_WIDE_BUS_TYPE* dst, int dst_byte_offset,
                          double* src, int src_offset,
                          int num_doubles)
{
#pragma HLS INLINE
    int start_elem = dst_byte_offset / sizeof(double);
    for (int j = 0; j < num_doubles; j++) {
#pragma HLS PIPELINE II=1
        int elem_idx = start_elem + j;
        int word_idx = elem_idx / DOUBLES_PER_WORD;
        int bit_offset = (elem_idx % DOUBLES_PER_WORD) * 64;
        double val = src[src_offset + j];
        ap_uint<64> bits;
        memcpy(&bits, &val, sizeof(double));
        dst[word_idx].range(bit_offset + 63, bit_offset) = bits;
    }
}

